//! `bsc bluetooth` — the DEFENSIVE Bluetooth analyzer, radio-free brain.
//!
//! The threats worth caring about are two, and this crate is the logic that catches them from the
//! ADVERTISING PLANE alone (what a standard adapter hears without transmitting):
//!
//! - **Spoofing / product impersonation.** A good spoof is signature-clean — it advertises the right
//!   name, address and services — so a blocklist cannot catch it. It is caught because it fails to
//!   match the *learned profile* of the real device: an [`address_twin`] (one address radiating from two
//!   places at once), an [`rssi_deviation`] (the wrong physical footprint), an [`interval_anomaly`]
//!   (the wrong cadence), or a [`service_mismatch`] (the identity reproduced imperfectly).
//! - **Abusive / malicious signals.** [`rogue_scan`] (a source flooding SCAN_REQs — active recon) and
//!   [`tracker_non_rotation`] (a random-address device that never rotates — an unwanted tracker).
//!
//! Everything here is PURE over a slice of [`Observation`]s plus an optional learned baseline, so the
//! decisions are tested without a microphone or a radio. Link-layer malformed-packet detection
//! (SweynTooth/BrakTooth) is a later phase that needs a sniffer, not a standard adapter — it is not here.

use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};

/// One BLE advertising-plane packet the observer heard.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Observation {
    /// The advertised address (BD_ADDR) as seen.
    pub addr: String,
    /// `public` or `random` — a random address is expected to ROTATE; one that does not is a signal.
    #[serde(default = "public_addr")]
    pub addr_type: String,
    /// Received signal strength, dBm (negative; closer to 0 is stronger).
    pub rssi: i32,
    /// Local name, if advertised.
    #[serde(default)]
    pub name: Option<String>,
    /// Manufacturer company id (from the manufacturer-specific data), if present.
    #[serde(default)]
    pub company_id: Option<u16>,
    /// Advertised service UUIDs.
    #[serde(default)]
    pub services: Vec<String>,
    /// Advertised TX power, if present.
    #[serde(default)]
    pub tx_power: Option<i32>,
    /// Whether the advertisement is connectable.
    #[serde(default)]
    pub connectable: bool,
    /// True when this observation is a SCAN_REQ we overheard (active-scan recon by `addr`), not an ADV.
    #[serde(default)]
    pub scan_req: bool,
    /// When observed (ms since the epoch).
    pub ts_ms: i64,
}

fn public_addr() -> String {
    "public".to_string()
}

/// The learned baseline for one device — its NORMAL operation. A spoof is anything that does not fit it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct DeviceProfile {
    pub addr: String,
    pub addr_type: String,
    pub count: u64,
    pub rssi_mean: f64,
    pub rssi_std: f64,
    pub rssi_min: i32,
    pub rssi_max: i32,
    pub first_ts: i64,
    pub last_ts: i64,
    /// Mean / std of the gap between consecutive advertisements (ms) — the cadence.
    pub interval_mean_ms: f64,
    pub interval_std_ms: f64,
    pub services: BTreeSet<String>,
    pub company_ids: BTreeSet<u16>,
    pub names: BTreeSet<String>,
    pub connectable: bool,
}

/// A detection. `kind` names the detector; `evidence` carries the numbers that justify it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Finding {
    pub kind: String,
    pub severity: String,
    pub addr: String,
    pub summary: String,
    pub evidence: serde_json::Value,
    pub ts_ms: i64,
}

/// The knobs. Defaults are deliberately conservative — this surface must not cry wolf.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Thresholds {
    /// A single address whose RSSI splits into two clusters at least this far apart (dB), both live at
    /// once, is one address radiating from two places — a clone.
    pub rssi_twin_gap_db: f64,
    /// A live observation this many std-devs off the device's baseline RSSI mean is a wrong footprint.
    pub rssi_deviation_sigma: f64,
    /// A live cadence whose ratio to the baseline mean falls outside `[1/r, r]` is the wrong device.
    pub interval_deviation_ratio: f64,
    /// A random address unbroken across at least this span (ms) has stopped rotating — a tracker.
    pub tracker_min_span_ms: i64,
    /// SCAN_REQs from one source above this rate (per minute) is active recon.
    pub scan_req_rate_per_min: f64,
    /// Below this many samples a profile is too thin to judge — silence beats a false alarm.
    pub min_samples: u64,
}

impl Default for Thresholds {
    fn default() -> Self {
        Thresholds {
            rssi_twin_gap_db: 18.0,
            rssi_deviation_sigma: 4.0,
            interval_deviation_ratio: 3.0,
            tracker_min_span_ms: 20 * 60 * 1000,
            scan_req_rate_per_min: 30.0,
            min_samples: 8,
        }
    }
}

fn mean_std(xs: &[f64]) -> (f64, f64) {
    if xs.is_empty() {
        return (0.0, 0.0);
    }
    let n = xs.len() as f64;
    let mean = xs.iter().sum::<f64>() / n;
    let var = if xs.len() > 1 {
        xs.iter().map(|x| (x - mean) * (x - mean)).sum::<f64>() / (n - 1.0)
    } else {
        0.0
    };
    (mean, var.sqrt())
}

/// Group observations by address and learn a [`DeviceProfile`] per device — the baseline of normal.
/// SCAN_REQ observations are excluded (they are the scanner's traffic, not a device advertising itself).
pub fn build_profiles(obs: &[Observation]) -> BTreeMap<String, DeviceProfile> {
    let mut by_addr: BTreeMap<&str, Vec<&Observation>> = BTreeMap::new();
    for o in obs.iter().filter(|o| !o.scan_req) {
        by_addr.entry(o.addr.as_str()).or_default().push(o);
    }
    let mut out = BTreeMap::new();
    for (addr, mut v) in by_addr {
        v.sort_by_key(|o| o.ts_ms);
        let rssi: Vec<f64> = v.iter().map(|o| o.rssi as f64).collect();
        let (rssi_mean, rssi_std) = mean_std(&rssi);
        let gaps: Vec<f64> = v.windows(2).map(|w| (w[1].ts_ms - w[0].ts_ms) as f64).collect();
        let (interval_mean_ms, interval_std_ms) = mean_std(&gaps);
        out.insert(
            addr.to_string(),
            DeviceProfile {
                addr: addr.to_string(),
                addr_type: v[0].addr_type.clone(),
                count: v.len() as u64,
                rssi_mean,
                rssi_std,
                rssi_min: v.iter().map(|o| o.rssi).min().unwrap_or(0),
                rssi_max: v.iter().map(|o| o.rssi).max().unwrap_or(0),
                first_ts: v.first().map(|o| o.ts_ms).unwrap_or(0),
                last_ts: v.last().map(|o| o.ts_ms).unwrap_or(0),
                interval_mean_ms,
                interval_std_ms,
                services: v.iter().flat_map(|o| o.services.iter().cloned()).collect(),
                company_ids: v.iter().filter_map(|o| o.company_id).collect(),
                names: v.iter().filter_map(|o| o.name.clone()).collect(),
                connectable: v.iter().any(|o| o.connectable),
            },
        );
    }
    out
}

fn finding(kind: &str, sev: &str, addr: &str, summary: String, evidence: serde_json::Value, ts: i64) -> Finding {
    Finding { kind: kind.into(), severity: sev.into(), addr: addr.into(), summary, evidence, ts_ms: ts }
}

/// One address whose RSSI splits into two well-separated clusters that are BOTH live in the same window
/// is one identity radiating from two places at once — a clone. The time overlap is what tells a clone
/// (concurrent) from a device that merely walked closer (a gradual, single-cluster drift).
pub fn address_twin(obs: &[Observation], t: &Thresholds) -> Vec<Finding> {
    let mut by_addr: BTreeMap<&str, Vec<&Observation>> = BTreeMap::new();
    for o in obs.iter().filter(|o| !o.scan_req) {
        by_addr.entry(o.addr.as_str()).or_default().push(o);
    }
    let mut out = Vec::new();
    for (addr, mut v) in by_addr {
        if (v.len() as u64) < t.min_samples {
            continue;
        }
        v.sort_by_key(|o| o.rssi);
        // Largest RSSI gap splits low/high.
        let (mut gap, mut split) = (0i32, 0usize);
        for i in 1..v.len() {
            let g = v[i].rssi - v[i - 1].rssi;
            if g > gap {
                gap = g;
                split = i;
            }
        }
        if (gap as f64) < t.rssi_twin_gap_db || split < 2 || v.len() - split < 2 {
            continue;
        }
        let (low, high) = (&v[..split], &v[split..]);
        // Do the two clusters overlap in TIME? (concurrent => clone; disjoint => movement)
        let low_lo = low.iter().map(|o| o.ts_ms).min().unwrap();
        let low_hi = low.iter().map(|o| o.ts_ms).max().unwrap();
        let high_lo = high.iter().map(|o| o.ts_ms).min().unwrap();
        let high_hi = high.iter().map(|o| o.ts_ms).max().unwrap();
        if low_lo <= high_hi && high_lo <= low_hi {
            out.push(finding(
                "address-twin",
                "high",
                addr,
                format!("one address at two signal levels at once ({} dB apart) — a clone", gap),
                serde_json::json!({ "gap_db": gap, "low_rssi": low.iter().map(|o| o.rssi).max(), "high_rssi": high.iter().map(|o| o.rssi).min(), "low_n": low.len(), "high_n": high.len() }),
                high_hi.max(low_hi),
            ));
        }
    }
    out
}

/// A live observation of a known device whose RSSI is many std-devs off its baseline — the identity is
/// right but the physical footprint is wrong, the signature of a spoofer transmitting from elsewhere.
pub fn rssi_deviation(obs: &[Observation], base: &BTreeMap<String, DeviceProfile>, t: &Thresholds) -> Vec<Finding> {
    let mut out = Vec::new();
    for o in obs.iter().filter(|o| !o.scan_req) {
        let Some(p) = base.get(&o.addr) else { continue };
        if p.count < t.min_samples || p.rssi_std <= 0.0 {
            continue;
        }
        let z = (o.rssi as f64 - p.rssi_mean) / p.rssi_std;
        if z.abs() >= t.rssi_deviation_sigma {
            out.push(finding(
                "rssi-deviation",
                "medium",
                &o.addr,
                format!("known device at {} dBm — {:.1}σ off its {:.0} dBm baseline (wrong location for its identity)", o.rssi, z, p.rssi_mean),
                serde_json::json!({ "rssi": o.rssi, "baseline_mean": p.rssi_mean, "baseline_std": p.rssi_std, "sigma": z }),
                o.ts_ms,
            ));
        }
    }
    out
}

/// A known device whose live advertising cadence is far off its baseline — a different transmitter
/// wearing its identity.
pub fn interval_anomaly(obs: &[Observation], base: &BTreeMap<String, DeviceProfile>, t: &Thresholds) -> Vec<Finding> {
    let live = build_profiles(obs);
    let mut out = Vec::new();
    for (addr, lp) in &live {
        let Some(p) = base.get(addr) else { continue };
        if p.count < t.min_samples || lp.count < 2 || p.interval_mean_ms <= 0.0 || lp.interval_mean_ms <= 0.0 {
            continue;
        }
        let ratio = lp.interval_mean_ms / p.interval_mean_ms;
        if ratio >= t.interval_deviation_ratio || ratio <= 1.0 / t.interval_deviation_ratio {
            out.push(finding(
                "interval-anomaly",
                "medium",
                addr,
                format!("advertising every {:.0} ms vs a {:.0} ms baseline ({:.1}x) — wrong cadence for its identity", lp.interval_mean_ms, p.interval_mean_ms, ratio),
                serde_json::json!({ "live_ms": lp.interval_mean_ms, "baseline_ms": p.interval_mean_ms, "ratio": ratio }),
                lp.last_ts,
            ));
        }
    }
    out
}

/// A known device now advertising a NAME, SERVICE or COMPANY the baseline never saw — the identity was
/// reproduced imperfectly, which a real device does not do.
pub fn service_mismatch(obs: &[Observation], base: &BTreeMap<String, DeviceProfile>, t: &Thresholds) -> Vec<Finding> {
    let mut out = Vec::new();
    let mut flagged: BTreeSet<String> = BTreeSet::new();
    for o in obs.iter().filter(|o| !o.scan_req) {
        let Some(p) = base.get(&o.addr) else { continue };
        if p.count < t.min_samples || flagged.contains(&o.addr) {
            continue;
        }
        let new_services: Vec<&String> = o.services.iter().filter(|s| !p.services.contains(*s)).collect();
        let new_company = o.company_id.filter(|c| !p.company_ids.contains(c));
        let new_name = o.name.as_ref().filter(|n| !p.names.contains(*n));
        if !new_services.is_empty() || new_company.is_some() || new_name.is_some() {
            flagged.insert(o.addr.clone());
            out.push(finding(
                "service-mismatch",
                "high",
                &o.addr,
                "known address advertising an identity attribute it never had — imperfect clone".to_string(),
                serde_json::json!({ "new_services": new_services, "new_company_id": new_company, "new_name": new_name }),
                o.ts_ms,
            ));
        }
    }
    out
}

/// A `random`-address device whose SAME address is unbroken across a long span has stopped rotating —
/// the signature of an unwanted tracker (a privacy-respecting device rotates its address regularly).
pub fn tracker_non_rotation(obs: &[Observation], t: &Thresholds) -> Vec<Finding> {
    let p = build_profiles(obs);
    let mut out = Vec::new();
    for (addr, prof) in &p {
        if !prof.addr_type.eq_ignore_ascii_case("random") || prof.count < t.min_samples {
            continue;
        }
        let span = prof.last_ts - prof.first_ts;
        if span >= t.tracker_min_span_ms {
            out.push(finding(
                "tracker-non-rotation",
                "medium",
                addr,
                format!("a random address that never rotated across {} min — an unwanted tracker", span / 60000),
                serde_json::json!({ "span_ms": span, "count": prof.count }),
                prof.last_ts,
            ));
        }
    }
    out
}

/// A source flooding SCAN_REQs above a sane rate is actively probing the space — recon, not a device
/// going about its business.
pub fn rogue_scan(obs: &[Observation], t: &Thresholds) -> Vec<Finding> {
    let mut by_src: BTreeMap<&str, Vec<i64>> = BTreeMap::new();
    for o in obs.iter().filter(|o| o.scan_req) {
        by_src.entry(o.addr.as_str()).or_default().push(o.ts_ms);
    }
    let mut out = Vec::new();
    for (addr, mut ts) in by_src {
        if ts.len() < 2 {
            continue;
        }
        ts.sort_unstable();
        let span_min = (ts[ts.len() - 1] - ts[0]) as f64 / 60000.0;
        let rate = if span_min > 0.0 { ts.len() as f64 / span_min } else { f64::INFINITY };
        if rate >= t.scan_req_rate_per_min {
            out.push(finding(
                "rogue-scan",
                "medium",
                addr,
                format!("{} scan requests in {:.1} min ({:.0}/min) — active recon", ts.len(), span_min, rate),
                serde_json::json!({ "count": ts.len(), "span_min": span_min, "rate_per_min": rate }),
                ts[ts.len() - 1],
            ));
        }
    }
    out
}

fn severity_rank(s: &str) -> u8 {
    match s {
        "high" => 0,
        "medium" => 1,
        _ => 2,
    }
}

/// Run every detector. Baseline-relative detectors run only when a `baseline` is supplied; the
/// self-contained ones (twin, tracker, rogue-scan) always run. Findings come back most-severe first.
pub fn analyze(obs: &[Observation], baseline: Option<&BTreeMap<String, DeviceProfile>>, t: &Thresholds) -> Vec<Finding> {
    let mut f = Vec::new();
    f.extend(address_twin(obs, t));
    f.extend(tracker_non_rotation(obs, t));
    f.extend(rogue_scan(obs, t));
    if let Some(b) = baseline {
        f.extend(rssi_deviation(obs, b, t));
        f.extend(interval_anomaly(obs, b, t));
        f.extend(service_mismatch(obs, b, t));
    }
    f.sort_by(|a, b| severity_rank(&a.severity).cmp(&severity_rank(&b.severity)).then(a.ts_ms.cmp(&b.ts_ms)));
    f
}
